function predictTree(tree: TreeNode, features: number[]) {
  let node = 0;
  while (tree.childrenLeft[node] !== -1 && tree.childrenRight[node] !== -1) {
    const featIdx = tree.feature[node];
    if (features[featIdx] <= tree.threshold[node]) node = tree.childrenLeft[node];
    else node = tree.childrenRight[node];
  }
  return tree.value[node];
}
